operation.document:
query GetAgentSessionDetails($id: String!) {
  agentSession(id: $id) {
    id
    status
    type
    createdAt
    updatedAt
    startedAt
    endedAt
    dismissedAt
    summary
    externalLink
    creator {
      name
    }
    appUser {
      name
    }
    dismissedBy {
      name
    }
    issue {
      identifier
      title
      url
    }
    activities(first: 20) {
      nodes {
        id
        createdAt
        content {
          ... on AgentActivityThoughtContent {
            type
            body
          }
          ... on AgentActivityActionContent {
            type
            action
            parameter
            result
          }
          ... on AgentActivityResponseContent {
            type
            body
          }
          ... on AgentActivityPromptContent {
            type
            body
          }
          ... on AgentActivityErrorContent {
            type
            body
          }
          ... on AgentActivityElicitationContent {
            type
            body
          }
        }
      }
    }
  }
}
